def _unquoted(text: str) -> str:
    """An expression with one layer of Obsidian's YAML quotes, around it, removed."""
    text = text.strip()
    if len(text) >= 2 and text[0] == text[-1] and text[0] in "\"'":
        quote, text = text[0], text[1:-1]
        if quote == '"':
            text = text.replace('\\"', '"').replace("\\\\", "\\")
        else:
            text = text.replace("''", "'")
    return text


def _expression_names(expression: str) -> list[str]:
    """The bare identifiers an Obsidian expression names: quoted strings, members (`.name`),
    functions (`name(`), `this`, `file`, `formula`, `true`, `false` and `null` removed."""
    text = re.sub(r'"[^"]*"', " ", _unquoted(expression))
    text = re.sub(r"'[^']*'", " ", text)
    names: list[str] = []
    for match in BASE_IDENT.finditer(text):
        name = match.group()
        if match.start() and text[match.start() - 1] == ".":
            continue
        if text[match.end():].lstrip().startswith("("):
            continue
        if name in BASE_LANGUAGE:
            continue
        names.append(name)
    return names


def _base_named(text: str) -> list[str]:
    """Every property `text` names: keys under `properties:`, entries of `order:`, the
    `property:` of a `sort` or `groupBy`, and filter and formula expressions."""
    named: list[str] = []
    lines = text.splitlines()
    i = 0
    while i < len(lines):
        raw = lines[i]
        stripped = raw.strip()
        indent = len(raw) - len(raw.lstrip())
        i += 1
        if not stripped or stripped.startswith("#"):
            continue
        header = BASE_HEADER.match(stripped)
        if not header:
            continue
        key, rest = header.group(1), header.group(2).strip()
        if key == "order" and rest.startswith("["):
            named.extend(rest.strip("[]").split(","))
            continue
        block: list[tuple[int, str]] = []
        while i < len(lines):
            line = lines[i]
            content = line.strip()
            if content and not content.startswith("#"):
                if len(line) - len(line.lstrip()) <= indent:
                    break
                block.append((len(line) - len(line.lstrip()), content))
            i += 1
        if key == "properties":
            child = min((depth for depth, _ in block), default=indent)
            for depth, content in block:
                if depth == child and ":" in content and not content.startswith("-"):
                    named.append(content.split(":", 1)[0].strip())
        elif key == "order":
            for _, content in block:
                if content.startswith("- "):
                    named.append(content[2:].strip())
        elif key in ("sort", "groupBy"):
            for _, content in block:
                match = BASE_PROPERTY.search(content)
                if match:
                    named.append(match.group(1).strip())
        else:
            if rest:
                named.append(rest)
            for _, content in block:
                if content.startswith("- "):
                    named.append(content[2:].strip())
                elif ":" in content:
                    value = content.split(":", 1)[1].strip()
                    if value:
                        named.append(value)
    return named


def _base_problems(docs: Path) -> list[str]:
    """The properties `docs/backlog.base` names that are not seed template fields."""
    base = docs / "backlog.base"
    if not base.is_file():
        return []
    fields_, _ = frontmatter(_read(docs / "templates" / "seed.md"))
    fields = set(fields_ or ())
    problems: list[str] = []
    seen: set[str] = set()
    for name in _base_named(_read(base)):
        for identifier in _expression_names(name):
            if identifier in seen:
                continue
            seen.add(identifier)
            if identifier not in fields:
                problems.append(
                    f"docs/backlog.base: {identifier} is not a field of docs/templates/seed.md"
                )
    return problems


